import { useState, useMemo, useRef, useEffect, useCallback } from "react";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, ReferenceDot } from "recharts";

// Section component defined OUTSIDE the main component so React doesn't unmount/remount
// children on every parent re-render. This is critical for canvas elements which would
// otherwise lose their painted content whenever the parent component re-renders.
function Section({ id, title, accent, children, badge, isOpen, onToggle }) {
  return (
    <div style={{
      background: "rgba(15, 22, 38, 0.6)",
      border: "1px solid rgba(96, 116, 156, 0.18)",
      borderRadius: 2,
      marginBottom: 16,
      overflow: "hidden",
    }}>
      <div onClick={onToggle}
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "12px 16px",
          cursor: "pointer",
          userSelect: "none",
          background: isOpen ? "rgba(0,0,0,0.15)" : "transparent",
          borderBottom: isOpen ? "1px solid rgba(96, 116, 156, 0.12)" : "none",
          transition: "background 0.15s",
        }}
        onMouseEnter={(e) => e.currentTarget.style.background = "rgba(0,0,0,0.25)"}
        onMouseLeave={(e) => e.currentTarget.style.background = isOpen ? "rgba(0,0,0,0.15)" : "transparent"}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{
            color: accent || "#9aa5bb",
            fontSize: 11,
            transition: "transform 0.2s",
            transform: isOpen ? "rotate(90deg)" : "rotate(0deg)",
            display: "inline-block",
            width: 10,
          }}>▶</span>
          <span style={{
            color: accent || "#9aa5bb",
            fontSize: 10,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            fontWeight: 500,
          }}>{title}</span>
        </div>
        {badge && <span style={{ color: "#6a7894", fontSize: 10 }}>{badge}</span>}
      </div>
      <div style={{ 
        padding: isOpen ? "16px" : "0 16px",
        maxHeight: isOpen ? "none" : 0,
        overflow: "hidden",
        opacity: isOpen ? 1 : 0,
        transition: "opacity 0.15s, padding 0.15s",
      }}>
        {children}
      </div>
    </div>
  );
}

// MTF stripe sample: renders a sinusoidal pattern at a given Michelson
// contrast and period (in arcsec), mapped to N cycles across the swatch
// using a fixed reference angular scale. Used in the MTF section to show
// what each (contrast, resolution) combination actually looks like.
function MtfStripeSwatch({ contrast, periodArcsec, refArcsec = 20, pixelScaleArcsec = null, width = 110, height = 30 }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const imageData = ctx.createImageData(width, height);
    const data = imageData.data;
    const mean = 0.5;
    const A = contrast / 2;  // Michelson: range = C → half-range = C/2
    if (!periodArcsec || periodArcsec <= 0) {
      // No resolved period at this contrast — render flat gray with note
      for (let i = 0; i < data.length; i += 4) {
        data[i] = 60; data[i+1] = 60; data[i+2] = 60; data[i+3] = 255;
      }
      ctx.putImageData(imageData, 0, 0);
      return;
    }
    const cycles = refArcsec / periodArcsec;
    if (pixelScaleArcsec && pixelScaleArcsec > 0) {
      // PIXEL SAMPLING MODE: render the cosine at the target Michelson
      // contrast, but sample it once per sky-pixel (centre value), then
      // upsample to canvas with nearest neighbour so each sky-pixel paints
      // a flat block.
      //
      // v329 fix: do NOT multiply by sinc(π·ν·Δ) here. The caller passes
      // the period at which the FULL system MTF (= MTF_opt · sinc) equals
      // the target contrast; the sinc roll-off is therefore already baked
      // into the chosen period. Applying it again inside the renderer
      // double-counted it and made the pixel swatch's Michelson contrast
      // equal to (target · sinc) — visibly dimmer than the optical row at
      // the same labelled contrast. Now both swatches render at the same
      // Michelson amplitude; the visual difference is purely the discrete
      // staircase + cosine-vs-pixel-grid beating ("irregular" cells),
      // which is what the pixel-resolved row is meant to illustrate.
      // Total physical width represented across the swatch:
      const widthArcsec = refArcsec;
      const px = pixelScaleArcsec;            // arcsec per pixel
      // How many sky-pixels fit across the swatch
      const numPx = Math.max(1, widthArcsec / px);
      // Width of one sky-pixel in canvas-pixels
      const swatchPxPerSkyPx = width / numPx;
      for (let x = 0; x < width; x++) {
        // Which sky pixel does this canvas column fall into?
        const skyPixIdx = Math.floor(x / swatchPxPerSkyPx);
        // Centre of that pixel in arcsec
        const x0_arcsec = (skyPixIdx + 0.5) * px;
        // Phase at the pixel centre
        const phase = (x0_arcsec / widthArcsec) * cycles * 2 * Math.PI;
        // Recorded value at the labelled Michelson contrast
        const v = mean + A * Math.cos(phase);
        const lum = Math.round(Math.max(0, Math.min(1, v)) * 255);
        for (let y = 0; y < height; y++) {
          const idx = (y * width + x) * 4;
          data[idx] = lum;
          data[idx + 1] = lum;
          data[idx + 2] = lum;
          data[idx + 3] = 255;
        }
      }
      ctx.putImageData(imageData, 0, 0);
      return;
    }
    // OPTICAL MODE (continuous cosine, original behaviour)
    for (let x = 0; x < width; x++) {
      const phase = (x / width) * cycles * 2 * Math.PI;
      const v = mean + A * Math.cos(phase);
      const lum = Math.round(Math.max(0, Math.min(1, v)) * 255);
      for (let y = 0; y < height; y++) {
        const idx = (y * width + x) * 4;
        data[idx] = lum;
        data[idx + 1] = lum;
        data[idx + 2] = lum;
        data[idx + 3] = 255;
      }
    }
    ctx.putImageData(imageData, 0, 0);
  }, [contrast, periodArcsec, refArcsec, pixelScaleArcsec, width, height]);
  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      style={{
        display: "block",
        imageRendering: "pixelated",
        borderRadius: 2,
        border: "1px solid rgba(154, 165, 187, 0.2)",
        margin: "0 auto",
      }}
    />
  );
}

// ============================================================
// PROFILE STORAGE — hybrid persistence
// ------------------------------------------------------------
// Tries Anthropic's window.storage first (works inside Claude artifacts,
// per-user across devices), then falls back to localStorage (works in any
// modern browser when deployed externally). Either way the user can also
// Export/Import a JSON file for cross-device transfer.
// ============================================================
const PROFILE_KEY = "dssim_profiles_v1";

async function loadProfilesAsync() {
  // 1. Try window.storage if present (Claude artifact runtime)
  try {
    if (typeof window !== "undefined" && window.storage && window.storage.get) {
      const result = await window.storage.get(PROFILE_KEY);
      if (result && result.value) {
        const parsed = JSON.parse(result.value);
        if (Array.isArray(parsed)) return parsed;
      }
    }
  } catch (_) { /* fall through to localStorage */ }
  // 2. Fall back to localStorage (browser-native, per-device)
  try {
    if (typeof window !== "undefined" && window.localStorage) {
      const raw = window.localStorage.getItem(PROFILE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
      }
    }
  } catch (_) { /* no storage available */ }
  return [];
}

async function saveProfilesAsync(profiles) {
  const payload = JSON.stringify(profiles);
  // Best-effort: write to both stores if available so profiles aren't lost
  // when the same code runs in different environments.
  let savedAnywhere = false;
  try {
    if (typeof window !== "undefined" && window.storage && window.storage.set) {
      await window.storage.set(PROFILE_KEY, payload);
      savedAnywhere = true;
    }
  } catch (_) {}
  try {
    if (typeof window !== "undefined" && window.localStorage) {
      window.localStorage.setItem(PROFILE_KEY, payload);
      savedAnywhere = true;
    }
  } catch (_) {}
  return savedAnywhere;
}

// Build a portable profile object from current state.
function makeProfile(name, sysA, sysB, target) {
  return {
    name,
    savedAt: new Date().toISOString(),
    sysA: { ...sysA },
    sysB: { ...sysB },
    target,
  };
}

// Encode profiles to a URL hash and decode them back. Lets users share or
// bookmark a single configuration. Hash is a base64-encoded JSON payload.
function encodeProfileToHash(profile) {
  try {
    const json = JSON.stringify(profile);
    // Use encodeURIComponent + btoa for unicode safety
    return "#cfg=" + btoa(unescape(encodeURIComponent(json)));
  } catch (_) { return ""; }
}
function decodeProfileFromHash(hash) {
  try {
    if (!hash || !hash.startsWith("#cfg=")) return null;
    const b64 = hash.slice("#cfg=".length);
    const json = decodeURIComponent(escape(atob(b64)));
    const parsed = JSON.parse(json);
    if (parsed && parsed.sysA && parsed.sysB) return parsed;
  } catch (_) {}
  return null;
}

