        // v720 Phase B.3 part 1: emission_neb compute pipeline. The full v97
        // dust field + 5 illuminators + filament/knot fine detail is ported
        // to WGSL. Reuses the same hash_i / fbm_i / ridged_i family as the
        // galaxy shader (same 32-bit integer hash, bit-equivalent for f64
        // hash inputs in the emission's pixel-scale coordinate range). Adds
        // ridgedSharp_i (cubed instead of squared) and worley_i (minimum
        // distance to nearest feature point in 3x3 cell neighborhood) used
        // only by emission. Illuminator positions and weights are embedded
        // as straight-line code rather than uniform fields since they're
        // hardcoded model constants. The JS bake (procMapCache) still runs
        // once per session to supply normalization constants (shNorm /
        // bbNorm) and the off-bake fallback values.
        const emissionShaderSrc = /* wgsl */`
struct EmParams {
  W: u32, H: u32,
  cxc: f32, cyc: f32,
  cx_base: f32, cy_base: f32, zoom_cam: f32,
  shNorm: f32, bbNorm: f32,
  img_w_m1: f32, img_h_m1: f32,
  img_w: f32, img_h: f32,
  _pad0: f32, _pad1: f32, _pad2: f32,
};

@group(0) @binding(0) var<storage, read_write> out_ha:   array<f32>;
@group(0) @binding(1) var<storage, read_write> out_oiii: array<f32>;
@group(0) @binding(2) var<storage, read_write> out_bb:   array<f32>;
@group(0) @binding(3) var<uniform> P: EmParams;

fn hash_i(ix: i32, iy: i32, seed: u32) -> f32 {
  let ux = u32(ix); let uy = u32(iy);
  var h: u32 = (ux + seed * 7919u) * 374761393u + (uy + seed * 6151u) * 668265263u;
  h = (h ^ (h >> 13u)) * 1274126177u;
  h = h ^ (h >> 16u);
  return f32(h) / 4294967295.0;
}
fn sm01(t: f32) -> f32 { return t * t * (3.0 - 2.0 * t); }
fn vnoise_i(x: f32, y: f32, seed: u32) -> f32 {
  let x0 = i32(floor(x));
  let y0 = i32(floor(y));
  let fx = sm01(x - floor(x));
  let fy = sm01(y - floor(y));
  let v00 = hash_i(x0,     y0,     seed);
  let v10 = hash_i(x0 + 1, y0,     seed);
  let v01 = hash_i(x0,     y0 + 1, seed);
  let v11 = hash_i(x0 + 1, y0 + 1, seed);
  return v00 * (1.0 - fx) * (1.0 - fy) + v10 * fx * (1.0 - fy)
       + v01 * (1.0 - fx) * fy        + v11 * fx * fy;
}
fn fbm_i(x: f32, y: f32, oct: i32, f0: f32, pers: f32, seed: u32) -> f32 {
  var v: f32 = 0.0; var a: f32 = 1.0; var t: f32 = 0.0; var f: f32 = f0;
  for (var i: i32 = 0; i < oct; i = i + 1) {
    v = v + vnoise_i(x * f, y * f, seed) * a;
    t = t + a; a = a * pers; f = f * 2.0;
  }
  return v / t;
}
fn ridgedSharp_i(x: f32, y: f32, oct: i32, f0: f32, pers: f32, seed: u32) -> f32 {
  var v: f32 = 0.0; var a: f32 = 1.0; var t: f32 = 0.0; var f: f32 = f0;
  for (var i: i32 = 0; i < oct; i = i + 1) {
    let n = vnoise_i(x * f, y * f, seed);
    let r = 1.0 - abs(2.0 * n - 1.0);
    v = v + r * r * r * a;  // cubed for sharp ridges
    t = t + a; a = a * pers; f = f * 2.0;
  }
  return v / t;
}
// Worley noise: minimum distance to nearest feature point in a 3x3
// neighborhood of grid cells. Feature point per cell has its offset
// driven by hash_i. Returns clamped to [0, 1].
fn worley_i(x: f32, y: f32, freq: f32, seed: u32) -> f32 {
  let xs = x * freq;
  let ys = y * freq;
  let xi = i32(floor(xs));
  let yi = i32(floor(ys));
  var md: f32 = 9.0;
  for (var gy: i32 = -1; gy <= 1; gy = gy + 1) {
    for (var gx: i32 = -1; gx <= 1; gx = gx + 1) {
      let cx = xi + gx;
      let cy = yi + gy;
      let px = f32(cx) + hash_i(cx * 3 + 1, cy * 7 + 5, seed);
      let py = f32(cy) + hash_i(cx * 5 + 3, cy * 2 + 9, seed);
      let dx = px - xs;
      let dy = py - ys;
      let d = sqrt(dx * dx + dy * dy);
      if (d < md) { md = d; }
    }
  }
  return min(1.0, md);
}
fn smoothstep_local(e0: f32, e1: f32, x: f32) -> f32 {
  let t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (gid.x >= P.W || gid.y >= P.H) { return; }

  let bx = P.cx_base + (f32(gid.x) - P.cxc) * P.zoom_cam;
  let by = P.cy_base + (f32(gid.y) - P.cyc) * P.zoom_cam;

  let oob_dx = max(0.0, max(-bx, bx - P.img_w_m1));
  let oob_dy = max(0.0, max(-by, by - P.img_h_m1));
  let overshoot = sqrt(oob_dx * oob_dx + oob_dy * oob_dy);
  let edgeFall = select(1.0, exp(-overshoot / 60.0), overshoot > 0.0);
  let x = clamp(bx, 0.0, P.img_w_m1);
  let y = clamp(by, 0.0, P.img_h_m1);

  // === verbatim v97 dust field port ===
  let dust1 = fbm_i(x * 1.0, y * 1.0, 5, 0.012, 0.55, 202u);
  let dust2 = fbm_i(x * 0.5, y * 0.5, 4, 0.025, 0.50, 202u);
  let dustRaw = (dust1 - 0.3) * 1.5 + (dust2 - 0.3) * 0.5;
  let k = 8.0;
  let arg = k * dustRaw;
  var dust: f32;
  if (arg > 30.0) { dust = dustRaw; }
  else if (arg < -30.0) { dust = 0.0; }
  else { dust = log(1.0 + exp(arg)) / k; }

  let stream = fbm_i(x * 0.04, y * 0.04, 4, 1.0, 0.5, 409u);
  if (stream > 0.55) { dust = dust * (1.0 + (stream - 0.55) * 1.5); }

  let fineA = fbm_i(x, y, 4, 0.05, 0.55, 307u);
  let fineB = fbm_i(x, y, 3, 0.50, 0.50, 311u);
  let fineCombined = ((fineA - 0.5) * 2.0) * 0.7 + ((fineB - 0.5) * 2.0) * 0.3;
  let transMask = smoothstep_local(0.005, 0.06, dust) * (1.0 - smoothstep_local(0.20, 0.40, dust));
  dust = dust * (1.0 + fineCombined * transMask * 0.6);
  if (dust < 0.0) { dust = 0.0; }

  let q1x = fbm_i(x, y, 4, 0.040, 0.55, 913u) - 0.5;
  let q1y = fbm_i(x, y, 4, 0.040, 0.55, 947u) - 0.5;
  let ix = x + 40.0 * q1x;
  let iy = y + 40.0 * q1y;
  let q2x = fbm_i(ix + 7000.0, iy + 7000.0, 3, 0.150, 0.55, 913u) - 0.5;
  let q2y = fbm_i(ix + 7000.0, iy + 7000.0, 3, 0.150, 0.55, 947u) - 0.5;
  let wx = ix + 15.0 * q2x;
  let wy = iy + 15.0 * q2y;
  let sf = fbm_i(wx + 5000.0, wy + 5000.0, 4, 0.0015, 0.55, 811u);

  let DUST_FREQ = 0.018;
  let DUST_PERS = 0.85;
  let cLow  = fbm_i(wx,          wy,          5, DUST_FREQ * 0.25, DUST_PERS, 503u);
  let cMid  = fbm_i(wx + 1000.0, wy + 1000.0, 5, DUST_FREQ,        DUST_PERS, 607u);
  let cHigh = fbm_i(wx + 2000.0, wy + 2000.0, 5, DUST_FREQ * 3.33, DUST_PERS, 709u);
  let wLow  = max(0.0, 1.0 - 2.0 * abs(sf - 0.17));
  let wMid  = max(0.0, 1.0 - 2.0 * abs(sf - 0.50));
  let wHigh = max(0.0, 1.0 - 2.0 * abs(sf - 0.83));
  let wSum = wLow + wMid + wHigh + 0.001;
  var contrast = (wLow * cLow + wMid * cMid + wHigh * cHigh) / wSum;
  contrast = max(0.0, (contrast - 0.40) / 0.60);
  contrast = pow(contrast, 6.0);  // DUST_CONTRAST
  dust = dust * (0.03 + 0.97 * contrast);
  if (dust < 0.0) { dust = 0.0; }

  let dxc = x - P.img_w * 0.5;
  let dyc = y - P.img_h * 0.5;
  let rc = sqrt(dxc * dxc + dyc * dyc);
  let centralMask = 1.0 - smoothstep_local(180.0, 360.0, rc);
  if (centralMask > 0.01) {
    let cdv = fbm_i(wx + 13000.0, wy + 13000.0, 1, 0.085, 0.55, 1213u);
    dust = dust * max(0.0, 1.0 + (cdv - 0.5) * 0.30 * centralMask);
  }
  // DUST_GAMMA = 1.2
  dust = pow(max(0.0, dust), 1.2);

  // === 5 illuminators (positions as fractions of IMG_W / IMG_H) ===
  var haIllum: f32 = 0.0;
  var oiiiIllum: f32 = 0.0;
  let IW = P.img_w;
  let IH = P.img_h;
  // Illum 0: 0.62, 0.32, B=0.65, S=22000, haW=0.50, oiiiW=1.00
  {
    let cx = IW * 0.62; let cy = IH * 0.32;
    let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
    let fo = 0.65 * exp(-d2 / 22000.0);
    haIllum = haIllum + fo * 0.50;
    oiiiIllum = oiiiIllum + fo * 1.00;
  }
  // Illum 1: 0.28, 0.40, B=0.50, S=14000, haW=0.55, oiiiW=1.00
  {
    let cx = IW * 0.28; let cy = IH * 0.40;
    let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
    let fo = 0.50 * exp(-d2 / 14000.0);
    haIllum = haIllum + fo * 0.55;
    oiiiIllum = oiiiIllum + fo * 1.00;
  }
  // Illum 2: 0.18, 0.72, B=1.10, S=36000, haW=1.00, oiiiW=0.10
  {
    let cx = IW * 0.18; let cy = IH * 0.72;
    let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
    let fo = 1.10 * exp(-d2 / 36000.0);
    haIllum = haIllum + fo * 1.00;
    oiiiIllum = oiiiIllum + fo * 0.10;
  }
  // Illum 3: 0.75, 0.68, B=1.20, S=42000, haW=1.00, oiiiW=0.08
  {
    let cx = IW * 0.75; let cy = IH * 0.68;
    let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
    let fo = 1.20 * exp(-d2 / 42000.0);
    haIllum = haIllum + fo * 1.00;
    oiiiIllum = oiiiIllum + fo * 0.08;
  }
  // Illum 4: 0.48, 0.55, B=0.85, S=28000, haW=1.00, oiiiW=0.15
  {
    let cx = IW * 0.48; let cy = IH * 0.55;
    let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
    let fo = 0.85 * exp(-d2 / 28000.0);
    haIllum = haIllum + fo * 1.00;
    oiiiIllum = oiiiIllum + fo * 0.15;
  }

  var haVal = dust * haIllum;
  var oiiiVal = dust * oiiiIllum;

  let FIL_FLOW = 40.0;
  let FIL_FREQ = 0.018;
  let FIL_STR = 5.0;
  let FIL_SHARP = 2.5;
  let KNOT_FREQ = 0.02;
  let KNOT_STR = 3.7;
  let KNOT_SHARP = 6.0;

  let presence = smoothstep_local(0.003, 0.04, dust) * (0.35 + 0.65 * smoothstep_local(0.02, 0.30, haIllum + oiiiIllum));
  if (presence > 0.001) {
    let fwx = x + FIL_FLOW * (fbm_i(x * 0.0008, y * 0.0008, 3, 1.0, 0.55, 5307u) - 0.5);
    let fwy = y + FIL_FLOW * (fbm_i(x * 0.0008 + 1000.0, y * 0.0008 + 1000.0, 3, 1.0, 0.55, 5413u) - 0.5);
    let filA = pow(max(0.0, (ridgedSharp_i(fwx,          fwy,          5, FIL_FREQ, 0.6, 5101u) - 0.50) / 0.50), FIL_SHARP);
    let filB = pow(max(0.0, (ridgedSharp_i(fwx + 3000.0, fwy + 3000.0, 5, FIL_FREQ, 0.6, 5203u) - 0.50) / 0.50), FIL_SHARP);
    let knotA = pow(max(0.0, 1.0 - worley_i(x, y, KNOT_FREQ, 6101u)), KNOT_SHARP);
    let knotB = pow(max(0.0, 1.0 - worley_i(x, y, KNOT_FREQ, 6203u)), KNOT_SHARP);
    let filStr  = FIL_STR  * presence;
    let knotStr = KNOT_STR * presence;
    let haGain   = 1.0 + filStr * (1.5 * filB - 0.5 * filA) + knotStr * (2.0 * knotA - 0.3 * knotB);
    let oiiiGain = 1.0 + filStr * (1.5 * filA - 0.5 * filB) + knotStr * (1.0 * knotB - 0.4 * knotA);
    haVal = haVal * max(0.0, haGain);
    oiiiVal = oiiiVal * max(0.0, oiiiGain);
    // v210 fine 1-3" filament carve (dust-gated only, not presence-gated)
    let fineFE = pow(max(0.0, (ridgedSharp_i(fwx * 3.3 + 900.0, fwy * 3.3 + 900.0, 4, FIL_FREQ, 0.62, 5101u) - 0.5) / 0.5), 2.4);
    let fineFEt = max(0.0, (fineFE - 0.18) / 0.82);
    let carveGate = smoothstep_local(0.01, 0.10, dust);
    let carve = 1.0 + 4.5 * fineFEt * carveGate;
    haVal = haVal * carve;
    oiiiVal = oiiiVal * carve;
  }

  // _sampleAtRaw returns {ha: haVal*3, oiii: oiiiVal*3, bb: (haVal+oiiiVal)*0.05}
  let rawHa   = haVal * 3.0;
  let rawOiii = oiiiVal * 3.0;
  let rawBb   = (haVal + oiiiVal) * 0.05;

  let idx = gid.y * P.W + gid.x;
  out_ha[idx]   = (rawHa   / P.shNorm) * edgeFall;
  out_oiii[idx] = (rawOiii / P.shNorm) * edgeFall;
  out_bb[idx]   = (rawBb   / P.bbNorm) * edgeFall;
}
`;

        try {
          const emModule = device.createShaderModule({ code: emissionShaderSrc });
          const emPipeline = await device.createComputePipelineAsync({
            layout: "auto",
            compute: { module: emModule, entryPoint: "main" },
          });
          if (cancelled) return;
          gpuRef.current.pipelines.emission = emPipeline;
          setGpuReady(s => ({ ...s, emission: true }));
          console.log("[v720] emission compute pipeline ready");
        } catch (e) {
          console.warn("[v720] emission shader compile failed:", e.message);
          if (!cancelled) setGpuError(`emission shader: ${e.message}`);
        }

        // v740 Phase B.4 part 1: planet_moon compute pipeline. Unlike v700-v730
        // (which replaced per-render sampleAt loops with GPU dispatches), the
        // moon port replaces the once-per-session BAKE. gen_moonDiscMap takes
        // ~5-15 s on iPad and only runs the first time a moon render is
        // requested (subsequently cache-hit from procMapCache). GPU brings
        // that cold-start cost down to ~50-200 ms. Differs from previous
        // shaders in three ways:
        // (1) Output is single-channel broadband (Float32Array IMG_W*IMG_H),
        //     not 3-channel ha/oiii/bb — moon doesn't go through the OSC
        //     Bayer split, it routes through the broadband channel.
        // (2) Procedural crater list (~4000 craters) is built on CPU using
        //     Mulberry32 (sequential RNG, can't be vectorized) and uploaded
        //     as a storage buffer. Brute-force iteration per pixel with
        //     distSq > checkR^2 early reject — at 1280x800 with 4000 craters
        //     that's ~20 G ops worst case, ~8-20 ms on modern integrated GPU.
        //     The JS path uses a 32-px spatial grid index that drops this
        //     to ~10-20 craters per pixel; brute-force is GPU-fine because
        //     early reject is cheap and divergence is bounded.
        // (3) Per-channel normalization (divide by max * 0.85) happens on
        //     CPU after readback since GPU reductions are non-trivial and
        //     this is a one-time bake. ~5 ms scan + scale.
        // The 11 hardcoded maria positions and 5 named featured craters
        // (Tycho, Copernicus, Kepler, Aristarchus, Plato) are embedded as
        // WGSL const arrays. Sun direction (sun_angle = -0.8, gibbous-phase
        // terminator on lower-left) and 3D illumination matrix are hardcoded
        // model constants.
        const moonShaderSrc = /* wgsl */`
struct MoonParams {
  W: u32, H: u32,
  cx: f32, cy: f32, R: f32,
  num_proc: u32,
  _pad0: f32, _pad1: f32,
  _pad2: f32, _pad3: f32, _pad4: f32, _pad5: f32,
  _pad6: f32, _pad7: f32, _pad8: f32, _pad9: f32,
};

@group(0) @binding(0) var<storage, read_write> out_map: array<f32>;
@group(0) @binding(1) var<storage, read> proc_craters: array<f32>;
@group(0) @binding(2) var<uniform> P: MoonParams;

// === Noise helpers (same family as galaxy/emission/jupiter) ===
fn hash_i(ix: i32, iy: i32, seed: u32) -> f32 {
  let ux = u32(ix); let uy = u32(iy);
  var h: u32 = (ux + seed * 7919u) * 374761393u + (uy + seed * 6151u) * 668265263u;
  h = (h ^ (h >> 13u)) * 1274126177u;
  h = h ^ (h >> 16u);
  return f32(h) / 4294967295.0;
}
fn sm01(t: f32) -> f32 { return t * t * (3.0 - 2.0 * t); }
fn vnoise_raw(x: f32, y: f32, seed: u32) -> f32 {
  let x0 = i32(floor(x));
  let y0 = i32(floor(y));
  let fx = sm01(x - floor(x));
  let fy = sm01(y - floor(y));
  let v00 = hash_i(x0,     y0,     seed);
  let v10 = hash_i(x0 + 1, y0,     seed);
  let v01 = hash_i(x0,     y0 + 1, seed);
  let v11 = hash_i(x0 + 1, y0 + 1, seed);
  return v00 * (1.0 - fx) * (1.0 - fy) + v10 * fx * (1.0 - fy)
       + v01 * (1.0 - fx) * fy        + v11 * fx * fy;
}
// vnoise(x, y, freq) = vnoise_raw(x * freq, y * freq, seed). Match JS.
fn vnoise_f(x: f32, y: f32, freq: f32, seed: u32) -> f32 {
  return vnoise_raw(x * freq, y * freq, seed);
}
fn fbm_i(x: f32, y: f32, oct: i32, f0: f32, pers: f32, seed: u32) -> f32 {
  var v: f32 = 0.0; var a: f32 = 1.0; var t: f32 = 0.0; var f: f32 = f0;
  for (var i: i32 = 0; i < oct; i = i + 1) {
    v = v + vnoise_raw(x * f, y * f, seed) * a;
    t = t + a; a = a * pers; f = f * 2.0;
  }
  return v / t;
}

// === Maria (11 hardcoded ellipses relative to disc center) ===
// Each is (cx_off/R, cy_off/R, rx/R, ry/R, depth, rot)
fn mareDarknessAt(x: f32, y: f32, P_: MoonParams) -> f32 {
  let R = P_.R;
  var d_max: f32 = 0.0;
  // The boundary noise sample is shared across all maria (matches JS impl
  // which computes it once outside the per-mare branch).
  let boundary = fbm_i(x * 0.05, y * 0.05, 3, 1.0, 0.5, 7u) * 0.18;

  // Macro per mare — manually unrolled because WGSL constant arrays are
  // awkward when one dimension is a struct.
  // Mare 0 — Imbrium
  {
    let cxm = P_.cx + R * (-0.30); let cym = P_.cy + R * (-0.38);
    let rx = R * 0.30; let ry = R * 0.22; let depth = 0.40; let rot = 0.1;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 1 — Serenitatis
  {
    let cxm = P_.cx + R * (-0.05); let cym = P_.cy + R * (-0.42);
    let rx = R * 0.20; let ry = R * 0.18; let depth = 0.42; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 2 — Tranquillitatis
  {
    let cxm = P_.cx + R * 0.20; let cym = P_.cy + R * (-0.30);
    let rx = R * 0.22; let ry = R * 0.20; let depth = 0.40; let rot = -0.1;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 3 — Crisium
  {
    let cxm = P_.cx + R * 0.55; let cym = P_.cy + R * (-0.38);
    let rx = R * 0.13; let ry = R * 0.10; let depth = 0.45; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 4 — Fecunditatis
  {
    let cxm = P_.cx + R * 0.45; let cym = P_.cy + R * (-0.05);
    let rx = R * 0.13; let ry = R * 0.18; let depth = 0.32; let rot = -0.2;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 5 — Nectaris
  {
    let cxm = P_.cx + R * 0.30; let cym = P_.cy + R * 0.08;
    let rx = R * 0.10; let ry = R * 0.12; let depth = 0.32; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 6 — Vaporum
  {
    let cxm = P_.cx + R * (-0.10); let cym = P_.cy + R * (-0.18);
    let rx = R * 0.10; let ry = R * 0.07; let depth = 0.30; let rot = 0.3;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 7 — Sinus Medii
  {
    let cxm = P_.cx + R * 0.05; let cym = P_.cy + R * (-0.05);
    let rx = R * 0.06; let ry = R * 0.05; let depth = 0.28; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 8 — Cognitum
  {
    let cxm = P_.cx + R * (-0.30); let cym = P_.cy + R * 0.05;
    let rx = R * 0.13; let ry = R * 0.10; let depth = 0.30; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 9 — Nubium
  {
    let cxm = P_.cx + R * (-0.20); let cym = P_.cy + R * 0.22;
    let rx = R * 0.16; let ry = R * 0.12; let depth = 0.32; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }
  // Mare 10 — Humorum
  {
    let cxm = P_.cx + R * (-0.42); let cym = P_.cy + R * 0.18;
    let rx = R * 0.10; let ry = R * 0.10; let depth = 0.34; let rot = 0.0;
    let dx = x - cxm; let dy = y - cym;
    let cR = cos(rot); let sR = sin(rot);
    let xr = dx * cR + dy * sR;
    let yr = -dx * sR + dy * cR;
    let distNorm = sqrt((xr / rx) * (xr / rx) + (yr / ry) * (yr / ry));
    if (distNorm < 1.0 + boundary) {
      let localDepth = depth * pow(max(0.0, 1.0 - distNorm), 0.7);
      d_max = max(d_max, localDepth);
    }
  }

  return d_max;
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (gid.x >= P.W || gid.y >= P.H) { return; }

  let x = f32(gid.x);
  let y = f32(gid.y);
  let dx = x - P.cx;
  let dy = y - P.cy;
  let r2 = dx * dx + dy * dy;

  if (r2 > P.R * P.R) {
    out_map[gid.y * P.W + gid.x] = 0.0;
    return;
  }

  let r_norm = sqrt(r2) / P.R;
  let cos_t = sqrt(1.0 - r_norm * r_norm);

  // 3D illumination: sun (0.6, -0.4, 0.7)
  let surface_dx = dx / P.R;
  let surface_dy = dy / P.R;
  let surface_dz = cos_t;
  var illumination = surface_dx * 0.6 + surface_dy * (-0.4) + surface_dz * 0.7;
  illumination = max(0.0, illumination);
  let terminator = pow(illumination, 0.85);

  // Base albedo
  var albedo: f32 = 0.74;
  let regionalNoise = fbm_i(x, y, 4, 0.006, 0.6, 7u);
  albedo = albedo + (regionalNoise - 0.5) * 0.12;

  // Mare darkening
  let dark = mareDarknessAt(x, y, P);
  albedo = albedo * (1.0 - dark);

  if (dark > 0.05) {
    let mareInternal = fbm_i(x, y, 5, 0.025, 0.5, 7u);
    albedo = albedo * (0.85 + 0.30 * mareInternal);
  }

  let reg1 = fbm_i(x, y, 5, 0.18, 0.5, 7u);
  albedo = albedo * (1.0 + (reg1 - 0.5) * 0.10);
  let reg2 = fbm_i(x + 1000.0, y + 1000.0, 4, 0.6, 0.4, 7u);
  albedo = albedo * (1.0 + (reg2 - 0.5) * 0.07);
  let speckle = vnoise_f(x, y, 2.5, 7u);
  albedo = albedo * (1.0 + (speckle - 0.5) * 0.04);

  // === Featured craters (5 unrolled) ===
  // sun direction for crater shadows (different from 3D illumination — this
  // is the 2D direction used for crater wall shadows)
  let sun_dx = cos(-0.8);
  let sun_dy = sin(-0.8);
  let R = P.R;

  // FEAT 0 — Tycho (fresh, has rays)
  {
    let cx_f = P.cx + R * (-0.20); let cy_f = P.cy + R * 0.55;
    let cr_f = R * 0.045; let depth_f = 0.55; let rim_f = 0.45;
    let cdx = x - cx_f; let cdy = y - cy_f;
    let cdist = sqrt(cdx * cdx + cdy * cdy);
    if (cdist <= cr_f * 8.0) {
      if (cdist < cr_f * 0.85) {
        let t = cdist / (cr_f * 0.85);
        albedo = albedo * (1.0 - depth_f * (1.0 - t * t));
        let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
        if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.4 * t); }
      } else if (cdist < cr_f * 1.20) {
        let rimFall = max(0.0, 1.0 - abs(cdist - cr_f) / (cr_f * 0.30));
        albedo = albedo * (1.0 + rim_f * rimFall * 1.4);
      } else {
        // Ray system (tycho offset = 0.2)
        let ang = atan2(cdy, cdx);
        var rayBrightness: f32 = 0.0;
        for (var k: i32 = 0; k < 9; k = k + 1) {
          let rayAng = (f32(k) / 9.0) * 6.283185307179586 + 0.2;
          let raw_diff = ang - rayAng + 3.141592653589793;
          let mod2pi = raw_diff - 6.283185307179586 * floor(raw_diff / 6.283185307179586);
          let angDiff = abs(mod2pi - 3.141592653589793);
          let rayWidth = 0.10 + vnoise_f(f32(k) * 73.0, cx_f, 1.0, 7u) * 0.10;
          if (angDiff < rayWidth) {
            let radial = exp(-(cdist - cr_f * 1.2) / (cr_f * 4.0));
            let broken = fbm_i(x * 0.04, y * 0.04 + f32(k) * 7.0, 3, 1.0, 0.5, 7u);
            let bv = (1.0 - angDiff / rayWidth) * radial * 0.20;
            let bv_b = bv * select(0.3, 1.0, broken > 0.4);
            rayBrightness = max(rayBrightness, bv_b);
          }
        }
        albedo = albedo * (1.0 + rayBrightness);
      }
    }
  }
  // FEAT 1 — Copernicus (fresh, has rays)
  {
    let cx_f = P.cx + R * (-0.18); let cy_f = P.cy + R * (-0.05);
    let cr_f = R * 0.060; let depth_f = 0.50; let rim_f = 0.42;
    let cdx = x - cx_f; let cdy = y - cy_f;
    let cdist = sqrt(cdx * cdx + cdy * cdy);
    if (cdist <= cr_f * 8.0) {
      if (cdist < cr_f * 0.85) {
        let t = cdist / (cr_f * 0.85);
        albedo = albedo * (1.0 - depth_f * (1.0 - t * t));
        let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
        if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.4 * t); }
      } else if (cdist < cr_f * 1.20) {
        let rimFall = max(0.0, 1.0 - abs(cdist - cr_f) / (cr_f * 0.30));
        albedo = albedo * (1.0 + rim_f * rimFall * 1.4);
      } else {
        // Ray system (copernicus offset = 0.6)
        let ang = atan2(cdy, cdx);
        var rayBrightness: f32 = 0.0;
        for (var k: i32 = 0; k < 9; k = k + 1) {
          let rayAng = (f32(k) / 9.0) * 6.283185307179586 + 0.6;
          let raw_diff = ang - rayAng + 3.141592653589793;
          let mod2pi = raw_diff - 6.283185307179586 * floor(raw_diff / 6.283185307179586);
          let angDiff = abs(mod2pi - 3.141592653589793);
          let rayWidth = 0.10 + vnoise_f(f32(k) * 73.0, cx_f, 1.0, 7u) * 0.10;
          if (angDiff < rayWidth) {
            let radial = exp(-(cdist - cr_f * 1.2) / (cr_f * 4.0));
            let broken = fbm_i(x * 0.04, y * 0.04 + f32(k) * 7.0, 3, 1.0, 0.5, 7u);
            let bv = (1.0 - angDiff / rayWidth) * radial * 0.20;
            let bv_b = bv * select(0.3, 1.0, broken > 0.4);
            rayBrightness = max(rayBrightness, bv_b);
          }
        }
        albedo = albedo * (1.0 + rayBrightness);
      }
    }
  }
  // FEAT 2 — Kepler (fresh, no rays)
  {
    let cx_f = P.cx + R * (-0.45); let cy_f = P.cy + R * (-0.05);
    let cr_f = R * 0.025; let depth_f = 0.45; let rim_f = 0.42;
    let cdx = x - cx_f; let cdy = y - cy_f;
    let cdist = sqrt(cdx * cdx + cdy * cdy);
    if (cdist <= cr_f * 1.20) {
      if (cdist < cr_f * 0.85) {
        let t = cdist / (cr_f * 0.85);
        albedo = albedo * (1.0 - depth_f * (1.0 - t * t));
        let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
        if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.4 * t); }
      } else {
        let rimFall = max(0.0, 1.0 - abs(cdist - cr_f) / (cr_f * 0.30));
        albedo = albedo * (1.0 + rim_f * rimFall * 1.4);
      }
    }
  }
  // FEAT 3 — Aristarchus (fresh, no rays)
  {
    let cx_f = P.cx + R * (-0.55); let cy_f = P.cy + R * (-0.22);
    let cr_f = R * 0.022; let depth_f = 0.45; let rim_f = 0.45;
    let cdx = x - cx_f; let cdy = y - cy_f;
    let cdist = sqrt(cdx * cdx + cdy * cdy);
    if (cdist <= cr_f * 1.20) {
      if (cdist < cr_f * 0.85) {
        let t = cdist / (cr_f * 0.85);
        albedo = albedo * (1.0 - depth_f * (1.0 - t * t));
        let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
        if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.4 * t); }
      } else {
        let rimFall = max(0.0, 1.0 - abs(cdist - cr_f) / (cr_f * 0.30));
        albedo = albedo * (1.0 + rim_f * rimFall * 1.4);
      }
    }
  }
  // FEAT 4 — Plato (not fresh, dark floor)
  {
    let cx_f = P.cx + R * (-0.20); let cy_f = P.cy + R * (-0.62);
    let cr_f = R * 0.040; let depth_f = 0.40; let rim_f = 0.20;
    let cdx = x - cx_f; let cdy = y - cy_f;
    let cdist = sqrt(cdx * cdx + cdy * cdy);
    if (cdist <= cr_f * 1.20) {
      if (cdist < cr_f * 0.85) {
        let t = cdist / (cr_f * 0.85);
        albedo = albedo * (1.0 - depth_f * (1.0 - t * t));
        albedo = albedo * 0.65;  // dark_floor
        let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
        if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.4 * t); }
      } else {
        let rimFall = max(0.0, 1.0 - abs(cdist - cr_f) / (cr_f * 0.30));
        albedo = albedo * (1.0 + rim_f * rimFall * 1.0);  // not fresh
      }
    }
  }

  // === Procedural craters (brute force with early reject) ===
  for (var i: u32 = 0u; i < P.num_proc; i = i + 1u) {
    let base = i * 8u;
    let cx_c = proc_craters[base + 0u];
    let cy_c = proc_craters[base + 1u];
    let cr = proc_craters[base + 2u];
    let cdx = x - cx_c;
    let cdy = y - cy_c;
    let cdist2 = cdx * cdx + cdy * cdy;
    let checkR = cr * 1.3;
    if (cdist2 > checkR * checkR) { continue; }
    let cdist = sqrt(cdist2);
    let cdepth = proc_craters[base + 3u];
    let crim   = proc_craters[base + 4u];
    let cage   = proc_craters[base + 5u];
    let cseed  = proc_craters[base + 6u];
    let cfresh = proc_craters[base + 7u];   // 1.0 = fresh, 0.0 = not
    let ang = atan2(cdy, cdx);
    let rimMod = 1.0 + 0.10 * (sin(ang * 3.0 + cseed) * 0.5 + sin(ang * 5.0 + cseed * 1.7) * 0.3);
    let effR = cr * rimMod;
    if (cdist > effR * 1.25) { continue; }
    let rimSharp = 1.0 - cage * 0.5;
    if (cdist < effR * 0.85) {
      let t = cdist / (effR * 0.85);
      let bowlDepth = cdepth * (1.0 - t * t) * (0.6 + 0.4 * rimSharp);
      albedo = albedo * (1.0 - bowlDepth);
      let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
      if (wall > 0.0) { albedo = albedo * (1.0 - wall * 0.40 * t); }
    } else if (cdist < effR * 1.20) {
      let rimFall = max(0.0, 1.0 - abs(cdist - effR) / (effR * 0.25));
      let wall = (cdx * sun_dx + cdy * sun_dy) / max(0.01, cdist);
      let sunBright = select(1.0, 1.0 + abs(wall) * 0.20, wall < 0.0);
      let freshMul = select(1.0, 1.3, cfresh > 0.5);
      albedo = albedo * (1.0 + crim * rimFall * sunBright * rimSharp * freshMul);
    }
  }

  // Apply illumination (terminator)
  var v = albedo * terminator;

  // M2 photographic grain
  if (v >= 0.01) {
    let fineGrain = fbm_i(x, y, 6, 0.5, 0.45, 7u);
    let ultraFine = vnoise_f(x, y, 3.0, 13u);
    let fineMod = (fineGrain - 0.5) * 0.08 + (ultraFine - 0.5) * 0.05;
    v = v * (1.0 + fineMod);
  }

  out_map[gid.y * P.W + gid.x] = clamp(v, 0.0, 1.0);
}
`;

