        // dim = ~25 cells, each with avg 2-3 stars in the periphery
        // (hundreds in the dense central King core). The cached spatial-
        // grid + star buffers are allocated ONCE on first dispatch and
        // reused across renders since the model is invariant.
        const gcShaderSrc = /* wgsl */`
struct GcParams {
  W: u32, H: u32,
  cxc: f32, cyc: f32,
  cx_base: f32, cy_base: f32, zoom_cam: f32,
  bbNorm: f32,
  img_w_m1: f32, img_h_m1: f32,
  arcsec_per_basepx: f32,
  intrinsic_sigma_arcsec: f32,
  search_radius_arcsec: f32,
  halfSpan_arcsec: f32,
  gridCell_arcsec: f32,
  cells: u32,
  num_stars: u32,
  cx_base_arcsec: f32, cy_base_arcsec: f32,
  _pad0: f32, _pad1: f32, _pad2: f32,
};

@group(0) @binding(0) var<storage, read_write> out_ha:   array<f32>;
@group(0) @binding(1) var<storage, read_write> out_oiii: array<f32>;
@group(0) @binding(2) var<storage, read_write> out_bb:   array<f32>;
@group(0) @binding(3) var<storage, read> stars_data:    array<f32>;
@group(0) @binding(4) var<storage, read> cell_starts:   array<u32>;
@group(0) @binding(5) var<storage, read> cell_indices:  array<u32>;
@group(0) @binding(6) var<uniform> P: GcParams;

// erf approximation: Abramowitz & Stegun 7.1.26 (~7-digit accuracy in f32).
fn erf_approx(x: f32) -> f32 {
  let sgn = select(1.0, -1.0, x < 0.0);
  let ax = abs(x);
  let a1: f32 =  0.254829592;
  let a2: f32 = -0.284496736;
  let a3: f32 =  1.421413741;
  let a4: f32 = -1.453152027;
  let a5: f32 =  1.061405429;
  let p: f32  =  0.3275911;
  let t = 1.0 / (1.0 + p * ax);
  let y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * exp(-ax * ax);
  return sgn * y;
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (gid.x >= P.W || gid.y >= P.H) { return; }

  // cam pixel → base px → sky arcsec
  let bx = P.cx_base + (f32(gid.x) - P.cxc) * P.zoom_cam;
  let by = P.cy_base + (f32(gid.y) - P.cyc) * P.zoom_cam;
  let ax_sky = (bx - P.cx_base) * P.arcsec_per_basepx;
  let ay_sky = (by - P.cy_base) * P.arcsec_per_basepx;
  // box half-extent in arcsec: matches JS sampleAt(bx, by, zoom_cam * 0.5)
  // where h = (zoom_cam * 0.5) * arcsec_per_basepx
  let h = P.zoom_cam * 0.5 * P.arcsec_per_basepx;

  // v941: resolution-adaptive sigma, mirrors JS sampleAtBoxArcsec.
  // sigEff = clamp(k*h, sigma_min, sigma_max); P.intrinsic_sigma_arcsec is the 1.8" cap.
  let sigEff = min(P.intrinsic_sigma_arcsec, max(0.4, 0.6 * h));
  let searchR = sigEff * 5.0;
  let queryR = h + searchR;
  let invSigSqrt2 = 1.0 / (sigEff * 1.4142135623730951);
  let inv_2h = 1.0 / (4.0 * h * h);  // 1 / area

  let cxLo = i32(floor((ax_sky - queryR + P.halfSpan_arcsec) / P.gridCell_arcsec));
  let cxHi = i32(floor((ax_sky + queryR + P.halfSpan_arcsec) / P.gridCell_arcsec));
  let cyLo = i32(floor((ay_sky - queryR + P.halfSpan_arcsec) / P.gridCell_arcsec));
  let cyHi = i32(floor((ay_sky + queryR + P.halfSpan_arcsec) / P.gridCell_arcsec));
  let cellsI = i32(P.cells);

  let cyA = max(0, cyLo);
  let cyB = min(cellsI - 1, cyHi);
  let cxA = max(0, cxLo);
  let cxB = min(cellsI - 1, cxHi);

  var haSum: f32 = 0.0;
  var oiiiSum: f32 = 0.0;
  var bbSum: f32 = 0.0;
  let queryR2 = queryR * queryR;

  for (var cy: i32 = cyA; cy <= cyB; cy = cy + 1) {
    for (var cx: i32 = cxA; cx <= cxB; cx = cx + 1) {
      let cell_idx = u32(cy * cellsI + cx);
      let start = cell_starts[cell_idx];
      let end   = cell_starts[cell_idx + 1u];
      for (var k: u32 = start; k < end; k = k + 1u) {
        let s_idx = cell_indices[k];
        let base = s_idx * 6u;
        let sax = stars_data[base + 0u];
        let say = stars_data[base + 1u];
        let dx = ax_sky - sax;
        let dy = ay_sky - say;
        if (dx * dx + dy * dy > queryR2) { continue; }
        let sflux  = stars_data[base + 2u];
        let sha_w  = stars_data[base + 3u];
        let soi_w  = stars_data[base + 4u];
        let sbb_w  = stars_data[base + 5u];
        let xLo = ax_sky - h - sax;
        let xHi = ax_sky + h - sax;
        let yLo = ay_sky - h - say;
        let yHi = ay_sky + h - say;
        let dEx = 0.5 * (erf_approx(xHi * invSigSqrt2) - erf_approx(xLo * invSigSqrt2));
        let dEy = 0.5 * (erf_approx(yHi * invSigSqrt2) - erf_approx(yLo * invSigSqrt2));
        let fluxInBox = sflux * dEx * dEy;
        let g = fluxInBox * inv_2h;
        haSum   = haSum   + g * sha_w;
        oiiiSum = oiiiSum + g * soi_w;
        bbSum   = bbSum   + g * sbb_w;
      }
    }
  }

  let idx = gid.y * P.W + gid.x;
  let inv = 1.0 / P.bbNorm;
  out_ha[idx]   = haSum * inv;
  out_oiii[idx] = oiiiSum * inv;
  out_bb[idx]   = bbSum * inv;
}
`;

