        // normalize by sumW (Lanczos) or count (box-avg). Bit-identity to
        // JS/WASM is NOT preserved (f32 vs f64 in the weighted accumulate);
        // structural identity matches the v401 Lanczos-3 / v403 box-avg
        // resampler.
        const resampleShaderSrc = /* wgsl */`
struct ResampleParams {
  srcW: u32, srcH: u32, dstW: u32, dstH: u32,
  canvas_to_src: f32,
  srcCenterX: f32, srcCenterY: f32,
  cnvCenterX: f32, cnvCenterY: f32,
  mode: u32,
  _pad0: u32, _pad1: u32, _pad2: u32,
  _pad3: u32, _pad4: u32, _pad5: u32,
};

@group(0) @binding(0) var<storage, read>       srcHa:  array<f32>;
@group(0) @binding(1) var<storage, read>       srcOi:  array<f32>;
@group(0) @binding(2) var<storage, read>       srcBb:  array<f32>;
@group(0) @binding(3) var<storage, read_write> dstHa:  array<f32>;
@group(0) @binding(4) var<storage, read_write> dstOi:  array<f32>;
@group(0) @binding(5) var<storage, read_write> dstBb:  array<f32>;
@group(0) @binding(6) var<storage, read_write> dstTot: array<f32>;
@group(0) @binding(7) var<uniform>             P:      ResampleParams;

const PI: f32 = 3.141592653589793;

fn lanczos3_w(x: f32) -> f32 {
  if (x == 0.0) { return 1.0; }
  let ax = abs(x);
  if (ax >= 3.0) { return 0.0; }
  let pix = PI * x;
  return (3.0 * sin(pix) * sin(pix / 3.0)) / (pix * pix);
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (gid.x >= P.dstW || gid.y >= P.dstH) { return; }

  let cxC = P.srcCenterX + (f32(gid.x) - P.cnvCenterX) * P.canvas_to_src;
  let cyC = P.srcCenterY + (f32(gid.y) - P.cnvCenterY) * P.canvas_to_src;
  let srcW_i = i32(P.srcW);
  let srcH_i = i32(P.srcH);

  var sumH: f32 = 0.0;
  var sumO: f32 = 0.0;
  var sumB: f32 = 0.0;

  // v798: three-state mode. mode==2 nearest-neighbor (deep upsample,
  // shows cam-pixel structure \u2014 the "minecraft" / PixInsight look that
  // honestly displays the sensor's sampling grid). mode==1 Lanczos-3
  // (mild upsample). mode==0 box-average (downsample).
  if (P.mode == 2u) {
    let sxR = i32(round(cxC));
    let syR = i32(round(cyC));
    let sxC = clamp(sxR, 0, srcW_i - 1);
    let syC = clamp(syR, 0, srcH_i - 1);
    let j = u32(syC) * P.srcW + u32(sxC);
    sumH = srcHa[j];
    sumO = srcOi[j];
    sumB = srcBb[j];
  } else if (P.mode == 1u) {
    let ix = i32(floor(cxC));
    let iy = i32(floor(cyC));
    let fx = cxC - floor(cxC);
    let fy = cyC - floor(cyC);
    var wxs: array<f32, 6>;
    wxs[0] = lanczos3_w(fx + 2.0);
    wxs[1] = lanczos3_w(fx + 1.0);
    wxs[2] = lanczos3_w(fx);
    wxs[3] = lanczos3_w(fx - 1.0);
    wxs[4] = lanczos3_w(fx - 2.0);
    wxs[5] = lanczos3_w(fx - 3.0);
    var wys: array<f32, 6>;
    wys[0] = lanczos3_w(fy + 2.0);
    wys[1] = lanczos3_w(fy + 1.0);
    wys[2] = lanczos3_w(fy);
    wys[3] = lanczos3_w(fy - 1.0);
    wys[4] = lanczos3_w(fy - 2.0);
    wys[5] = lanczos3_w(fy - 3.0);
    var sumW: f32 = 0.0;
    for (var dy: i32 = 0; dy < 6; dy = dy + 1) {
      let sy = iy - 2 + dy;
      let syC = clamp(sy, 0, srcH_i - 1);
      let wy = wys[dy];
      let rowBase = u32(syC) * P.srcW;
      for (var dx: i32 = 0; dx < 6; dx = dx + 1) {
        let sx = ix - 2 + dx;
        let sxC = clamp(sx, 0, srcW_i - 1);
        let wx = wxs[dx];
        let w = wx * wy;
        let j = rowBase + u32(sxC);
        sumH = sumH + srcHa[j] * w;
        sumO = sumO + srcOi[j] * w;
        sumB = sumB + srcBb[j] * w;
        sumW = sumW + w;
      }
    }
    let inv = select(0.0, 1.0 / sumW, sumW != 0.0);
    sumH = sumH * inv;
    sumO = sumO * inv;
    sumB = sumB * inv;
  } else {
    // Box-average downsample
    let halfWindow = P.canvas_to_src * 0.5;
    let cx_lo = max(0, i32(floor(cxC - halfWindow)));
    let cx_hi = min(srcW_i - 1, i32(ceil(cxC + halfWindow)));
    let cy_lo = max(0, i32(floor(cyC - halfWindow)));
    let cy_hi = min(srcH_i - 1, i32(ceil(cyC + halfWindow)));
    var count: u32 = 0u;
    for (var cy: i32 = cy_lo; cy <= cy_hi; cy = cy + 1) {
      let rowBase = u32(cy) * P.srcW;
      for (var cx: i32 = cx_lo; cx <= cx_hi; cx = cx + 1) {
        let j = rowBase + u32(cx);
        sumH = sumH + srcHa[j];
        sumO = sumO + srcOi[j];
        sumB = sumB + srcBb[j];
        count = count + 1u;
      }
    }
    if (count > 0u) {
      let inv = 1.0 / f32(count);
      sumH = sumH * inv;
      sumO = sumO * inv;
      sumB = sumB * inv;
    }
  }

  sumH = max(0.0, sumH);
  sumO = max(0.0, sumO);
  sumB = max(0.0, sumB);

  let idx = gid.y * P.dstW + gid.x;
  dstHa[idx]  = sumH;
  dstOi[idx]  = sumO;
  dstBb[idx]  = sumB;
  dstTot[idx] = sumH + sumO + sumB;
}
`;

