    // independently -- normalizing knots to white and, because the red divisor
    // inflates ~3x more than green, shifting the whole continuum green. Use ONE
    // shared divisor instead so the boosted knots stay red and the continuum
    // fades to a dim warm tint (the real Ha-galaxy look). Downstream TARGETS
    // multipliers scale to absolute signal level.
    let invBb, invHa, invOiii;
