                    const cxo = x + (si + 0.5) * inv - 0.5;
                    const cyo = y + (sj + 0.5) * inv - 0.5;
                    const bx = cx_base + (cxo - cx_canvas) * zoom;
                    const by = cy_base + (cyo - cy_canvas) * zoom;
