                      const dx = bx < 0 ? -bx : (bx >= bake_W - 1 ? bx - (bake_W - 1) : 0);
                      const dy = by < 0 ? -by : (by >= bake_H - 1 ? by - (bake_H - 1) : 0);
                      const overshoot = Math.sqrt(dx * dx + dy * dy);
                      const sx = Math.max(0, Math.min(bake_W - 1, Math.round(bx)));
                      const sy = Math.max(0, Math.min(bake_H - 1, Math.round(by)));
                      const fall = Math.exp(-overshoot / 60);
                      ah += dsoChannels.ha[sy * bake_W + sx] * fall;
