            _paramsF32[ 1] = sigCoefO;
            _paramsF32[ 2] = sigCoefB;
            _paramsF32[ 3] = t_seconds;
            _paramsF32[ 4] = perSubScale;
            _paramsF32[ 5] = fullWell;
            _paramsF32[ 6] = totalSubs;
            _paramsF32[ 7] = skyMean;
            _paramsF32[ 8] = skyMean_ha;
            _paramsF32[ 9] = skyMean_oiii;
            _paramsF32[10] = skyMean_bb;
            _paramsF32[11] = Lsky_ha;
            _paramsF32[12] = Lsky_oi;
            _paramsF32[13] = Lsky_bb;
            _paramsF32[14] = bayer_ha;
            _paramsF32[15] = bayer_oiii;
            _paramsF32[16] = bayer_bb;
            _paramsF32[17] = darkMean_ha;
            _paramsF32[18] = darkMean_oiii;
            _paramsF32[19] = darkMean_bb;
            _paramsF32[20] = Ldk_ha;
            _paramsF32[21] = Ldk_oi;
            _paramsF32[22] = Ldk_bb;
            _paramsF32[23] = readSig_R;
            _paramsF32[24] = readSig_G;
            _paramsF32[25] = readSig_B;
            _paramsF32[26] = fpnSigma;
